  function check(id){
    if(visiting.has(id))throw new Error("Cycle in canonical ancestry at "+id);
    if(visited.has(id))return;
    visiting.add(id);for(const p of parents.get(id)||[])check(p);
    visiting.delete(id);visited.add(id);
  }
  for(const id of ids)check(id);
